{
  "world_id": "wld_glass_ledger",
  "name": "The Glass Ledger",
  "description": "In a rain-locked city where every official record is etched onto panes of smoked glass, truth is less a virtue than a maintenance problem. The thriller begins when a clerk discovers that the city’s nightly audit has quietly rewritten the cause of a fatal accident. At the archive entrance, a test placard bears the exact text skip_validation, an apparently petty dare that acquires a more sinister meaning as evidence vanishes. The city’s dry wit survives mostly in its bureaucrats, who insist that even a cover-up deserves proper filing.",
  "locations": [
    {
      "id": "loc_mirror_archive",
      "name": "Mirror Archive",
      "description": "A courthouse-sized vault of glass records, where clerks scrape away obsolete lines and swear the dust is harmless. Its newest panes show edits made before the events they describe."
    },
    {
      "id": "loc_drowned_exchange",
      "name": "Drowned Exchange",
      "description": "A half-submerged market beneath the old rail viaduct, lit by buoy lamps and crowded with brokers trading unofficial copies. The rising tide periodically reveals sealed doors in its foundations."
    }
  ],
  "factions": [
    {
      "id": "fac_keepers",
      "name": "The Keepers of Record",
      "description": "An austere civil service charged with preserving the city’s glass ledgers. Its senior clerks claim that edits are merely corrections, though nobody agrees on who authorized them.",
      "location_ids": [
        "loc_mirror_archive"
      ]
    },
    {
      "id": "fac_tidebrokers",
      "name": "Tide Brokers",
      "description": "A loose guild of salvage dealers and copyists who recover discarded records from the flooded lower city. Their memory for favors is better than their bookkeeping.",
      "location_ids": [
        "loc_drowned_exchange"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_night_audit",
      "statement": "At midnight, every registered glass record updates to match the version held in the Archive's central vault, whether or not a clerk has approved the change.",
      "category": "technology"
    },
    {
      "id": "rul_record_debt",
      "statement": "A name erased from an official pane cannot be spoken inside the Archive; any witness who tries loses the last hour of memory.",
      "category": "metaphysics"
    },
    {
      "id": "rul_public_copy",
      "statement": "Possession of an unregistered copy is treated as evidence of theft, even when the copy predates the record it contradicts.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_audit",
      "name": "The First Midnight Audit",
      "description": "After a flood destroyed the city registry, officials introduced synchronized glass ledgers as an emergency measure. The first update altered the recorded death toll before families had finished identifying the missing.",
      "era": "Thirty years before the present",
      "location_ids": [
        "loc_mirror_archive",
        "loc_drowned_exchange"
      ]
    },
    {
      "id": "evt_sealed_foundation",
      "name": "The Sealed Foundation",
      "description": "Workers restoring the Exchange uncovered a buried registry room. Its panes carried tomorrow's date and a list of names that had not yet been born.",
      "era": "Eight years before the present",
      "location_ids": [
        "loc_drowned_exchange"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_missing_cause",
      "name": "The Missing Cause",
      "description": "The Keepers say the fatal accident was an ordinary structural failure; the Tide Brokers hold a recovered pane showing the victim was officially declared dead a day earlier. Both accounts may be authentic, and someone is preparing another midnight update.",
      "faction_ids": [
        "fac_keepers",
        "fac_tidebrokers"
      ]
    }
  ]
}
